export default async function ListPage() {
  const res = await fetch('{{api_url}}', { next: { revalidate: 60 } });
  const items: any[] = await res.json();
  return (
    <ul className="p-6 space-y-2">
      {items.map((it, i) => (
        <li key={i} className="border-b py-2">{it.{{item_field}}}</li>
      ))}
    </ul>
  );
}
